#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int m;scanf("%d",&m);
int cnt[26]={0};
for(int i=0;i<m;++i){char c[4];scanf("%s",c);++cnt[c[0]-'A'];}
int n;scanf("%d",&n);
priority_queue<int>pq;
for(int i=0;i<26;++i)if(cnt[i])pq.push(cnt[i]);
int time=0;
while(!pq.empty()){
vector<int>tmp;
for(int i=0;i<=n;++i){
if(!pq.empty()){tmp.push_back(pq.top()-1);pq.pop();}
++time;
if(pq.empty()){bool any=false;for(int v:tmp)if(v>0)any=true;
if(!any)break;}}
for(int v:tmp)if(v>0)pq.push(v);}
printf("%d\n",time);return 0;}

